begin;
create extension if not exists pgtap with schema extensions;
select plan(14);
-- Same transaction setting used by the Storage API; fixture transaction rolls back.
set local storage.allow_delete_query='true';
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values ('40000000-0000-4000-8000-000000000001','handout-policy-dm@verification.test','{}','{}'),('40000000-0000-4000-8000-000000000002','handout-policy-player@verification.test','{}','{}');
insert into public.party_members(party_id,user_id,role) values ('00000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','dungeon-master'),('00000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000002','player');
insert into storage.objects(bucket_id,name,metadata) values ('party-handouts','00000000-0000-4000-8000-000000000001/40000000-0000-4000-8000-000000000003','{"size":68,"mimetype":"image/png"}');
set local role authenticated;
set local "request.jwt.claim.sub"='40000000-0000-4000-8000-000000000001';
select lives_ok($$insert into public.party_handouts(id,party_id,title,mime,size,digest) values ('40000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000001','Letter','image/png',68,repeat('a',64))$$,'DM commits private metadata only after object exists');
select is((select visibility from public.party_handouts where id='40000000-0000-4000-8000-000000000003'),'private','uploads start private');
select lives_ok($$select public.change_party_handout('40000000-0000-4000-8000-000000000003',1,'40000000-0000-4000-8000-000000000006','rename','Renamed')$$,'DM renames metadata');
select throws_ok($$update public.party_handouts set visibility='revealed' where id='40000000-0000-4000-8000-000000000003'$$,'42501',null,'Ticket02 cannot reveal through direct column update');
select throws_ok($$insert into public.party_handouts(id,party_id,title,mime,size,digest) values ('40000000-0000-4000-8000-000000000004','00000000-0000-4000-8000-000000000001','Missing','image/png',68,repeat('a',64))$$,'P0001','Upload usable content before saving the Handout','missing object denied');
with deleted as(delete from storage.objects where bucket_id='party-handouts' and name='00000000-0000-4000-8000-000000000001/40000000-0000-4000-8000-000000000003' returning id)select is((select count(*) from deleted),0::bigint,'committed object cannot be removed by compensation');
set local "request.jwt.claim.sub"='40000000-0000-4000-8000-000000000002';
select is((select count(*) from public.party_handouts),0::bigint,'Player cannot enumerate private metadata');
select is((select count(*) from storage.objects where bucket_id='party-handouts'),0::bigint,'Player cannot enumerate private objects');
select throws_ok($$update public.party_handouts set title='Leak'$$,'42501',null,'Player cannot directly retitle private metadata');
select throws_ok($$insert into storage.objects(bucket_id,name,metadata) values ('party-handouts','00000000-0000-4000-8000-000000000001/40000000-0000-4000-8000-000000000005','{"size":68,"mimetype":"image/png"}')$$,'42501',null,'Player cannot insert objects');
set local role anon;
select throws_ok($$select * from public.party_handouts$$,'42501',null,'anonymous metadata access denied');
select is((select count(*) from storage.objects where bucket_id='party-handouts'),0::bigint,'anonymous private objects denied');
reset role;
select is((select public from storage.buckets where id='party-handouts'),false,'bucket remains private');
select is((select file_size_limit from storage.buckets where id='party-handouts'),20971520::bigint,'storage enforces 20 MiB size limit');
select * from finish();
rollback;
